{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Pamiparib, the closest analogue, shares the fluorinated fused lactam/indole core and has near-complete absorption and high oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "CP-409,092, which contains the same p-(methylaminomethyl)phenyl group as the query, has 69% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vonoprazan, bearing a closely related methylaminomethyl-aryl group and basic amine, has an estimated human oral bioavailability of 36%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Milrinone, a small polar heteroaromatic lactam, has about 92-95% absolute oral bioavailability in humans, showing that polar/ionizable small molecules can be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Sunitinib, a fluorinated lactam with a basic amine side chain, has about 50% absolute oral bioavailability in humans under fasted conditions, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Safinamide, a basic amine with a fluorinated aromatic ring, has 95.0% absolute oral bioavailability in healthy subjects in the fasted state, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Mizolastine, a basic drug with a fluorophenyl group, has about 65% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A water-soluble non-metabolized TC analogue with a fluorinated oxindole lactam had only about 10% oral bioavailability in humans, providing a low-bioavailability counterexample; however, its low similarity and distinct physicochemical features limit transfer to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F ≥ 20%). Multiple human absolute-bioavailability data for analogues sharing key query features—methylaminomethylphenyl group, fluorinated aromatic/lactam, or basic amine—range from 36% to 95%, all above threshold. The only low-bioavailability analogue is structurally distant and not clearly transferable. Physicochemical ionization concerns are outweighed by consistent experimental evidence.",
  "evidence_gaps": [
    "No direct human or animal pharmacokinetic data for the query molecule itself.",
    "All analogues have low Morgan similarity (<0.28), limiting structural transferability.",
    "The query's very low neutral fraction and low logD at pH 7.4 could reduce passive permeability; no direct permeability/transport data are available.",
    "Metabolic stability and efflux-transporter liability of the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

